// scripts/post-pinterest-pin.js
// CLI agent: posts a Pin to your Pinterest account for a given product.
//
// Reads the product from the SAME database the live site uses
// (DigitalProduct collection, matched by slug), uses the pin image already
// generated by generate-pinterest-pin.js (public/pinterest-pins/<slug>.png,
// served live at https://www.shopyor.com/pinterest-pins/<slug>.png), and
// creates the Pin via the Pinterest v5 API using the access token captured
// by the Pinterest OAuth login (stored in the pinterestauths collection —
// see lib/models/PinterestAuth.js / lib/authOptions.js).
//
//   Run: node scripts/post-pinterest-pin.js <product-slug> [board-id]
//   Example: node scripts/post-pinterest-pin.js uk-ks2-maths-year-6-fractions-ws02
//
// Prerequisites:
//   1. Generate the pin image first if it doesn't exist yet:
//        node generate-pinterest-pin.js <pdf-path> <slug> "<title>" "<price>"
//   2. Sign in once via the Pinterest OAuth flow (visit
//        https://www.shopyor.com/api/auth/signin/pinterest
//      and approve) so a fresh access token is stored in the DB. Pinterest
//      access tokens expire (~30 days) — repeat this when posts start
//      failing with 401.
require("dotenv").config({ path: ".env.local" });
const { MongoClient } = require("mongodb");

const SITE = process.env.NEXT_PUBLIC_BASE_URL || "https://www.shopyor.com";
const PINTEREST_API_BASE =
  process.env.PINTEREST_API_BASE || "https://api.pinterest.com/v5";

async function main() {
  const [, , slug, boardIdArg] = process.argv;
  if (!slug) {
    console.error(
      "Usage: node scripts/post-pinterest-pin.js <product-slug> [board-id]",
    );
    process.exit(1);
  }

  const uri = process.env.DATABASE_URL;
  if (!uri) {
    console.error("❌ DATABASE_URL is not set in .env.local");
    process.exit(1);
  }

  const client = new MongoClient(uri);
  await client.connect();
  const db = client.db();

  try {
    const product = await db
      .collection("digitalproducts")
      .findOne({ slug: slug.toLowerCase() });
    if (!product) {
      console.error(`❌ No DigitalProduct found with slug "${slug}"`);
      process.exit(1);
    }

    const auth = await db.collection("pinterestauths").findOne({ _id: "main" });
    const accessToken = auth?.accessToken || process.env.PINTEREST_ACCESS_TOKEN;
    if (!accessToken) {
      console.error(
        "❌ No Pinterest access token found. Sign in first via " +
          `${SITE}/api/auth/signin/pinterest`,
      );
      process.exit(1);
    }

    const boardId = boardIdArg || process.env.PINTEREST_BOARD_ID;
    if (!boardId) {
      console.error(
        "❌ No board id. Pass one as the 2nd argument or set PINTEREST_BOARD_ID.",
      );
      process.exit(1);
    }

    const imageUrl = `${SITE}/pinterest-pins/${product.slug}.png`;
    const linkUrl = `${SITE}${product.href}`;

    const body = {
      board_id: boardId,
      title: product.title.slice(0, 100),
      description: product.description.slice(0, 500),
      link: linkUrl,
      media_source: {
        source_type: "image_url",
        url: imageUrl,
      },
    };

    const res = await fetch(`${PINTEREST_API_BASE}/pins`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });

    const data = await res.json().catch(() => ({}));

    if (!res.ok) {
      if (res.status === 401) {
        console.error(
          "❌ Pinterest rejected the access token (401 — likely expired).\n" +
            `   Sign in again at ${SITE}/api/auth/signin/pinterest, then retry.`,
        );
      } else {
        console.error(`❌ Pinterest API error (${res.status}):`, data);
      }
      process.exit(1);
    }

    console.log(`✅ Pin created for "${product.title}"`);
    console.log(`   Pin ID: ${data.id}`);
    console.log(`   Image: ${imageUrl}`);
    console.log(`   Link: ${linkUrl}`);
  } finally {
    await client.close();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
